use semio_s_artifact_layout_layout_model::ParentPage;
use semio_s_artifact_layout_layout_diff::LayoutDiff;
use semio_framework_value::retained_clone::RetainedCloneClose;
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_s_artifact_layout_layout_mutations_decisions::parent_creation::*;

use semio_framework_value::{RetireOwned,retained_clone::{RetainedCloneSource,RetainedCloneClose}};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Sync>(v:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});RetainedCloneSource::admit_owned(v,(),g).unwrap_or_else(|(e,_,_)|panic!("{e}")).0}
fn close_source<T:RetireOwned+Sync>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let d=s.next_close_demand(256).unwrap();s.close_step(grant(d)).unwrap();}}
fn retire<T:RetireOwned>(v:T){let mut v=Some(v);let mut r=RetainedCloneClose::default();while v.is_some()||!r.is_empty(){let d=r.next_owner_demands::<T>(v.is_some(),&None,256).unwrap();if !r.is_empty(){r.step_granted(grant(d)).unwrap();}else{r.begin_granted(&mut v,grant(d)).unwrap();}}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->RetainedCloneStep)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(g));step}
fn close(p:&mut ParentCreationOutput){p.begin_close();while !p.terminal_is_empty(){let d=p.close_demand(256).unwrap();assert_eq!(observe(Default::default(),||p.close_step(Default::default()).unwrap()).progress(),Default::default());observe(grant(d),||p.close_step(grant(d)).unwrap());}}
#[test]
fn original_parent_rows_keep_physical_custody_and_independent_cache_witnesses(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let common:serde_json::Value=serde_json::from_str(include_str!("../../../🎚️simple/🧪️tests/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let event=LayoutMutation::CreateParentPage(crate::create_parent_page::CreateParentPage{page:decode(&row["page"]),index:row["index"].as_u64().map(|i|i as usize)});for cut in std::iter::once(usize::MAX).chain(corpus["cuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize)){let mut authored=source(event.clone());let mut base=source(decode::<LayoutSnapshot>(&common["base"]));let mut prepared=vec![event.clone()];let(id,frames,layers)=match &prepared[0]{LayoutMutation::CreateParentPage(p)=>(p.page.id.as_ptr(),p.page.frames.as_ptr(),p.page.layers.as_ptr()),_=>unreachable!()};let mut diff=LayoutDiff::default();let mut owner=ParentCreationOutput::default();for at in 0..cut{if owner.ready(){break}assert!(at<100000);let d=owner.demand(authored.borrow(),base.borrow(),256).unwrap();assert_eq!(observe(Default::default(),||owner.advance(&mut prepared,authored.borrow(),base.borrow(),&mut diff,Default::default()).unwrap()).progress(),Default::default());observe(grant(d),||owner.advance(&mut prepared,authored.borrow(),base.borrow(),&mut diff,grant(d)).unwrap());}if cut==usize::MAX{assert!(owner.ready());let insertion=&diff.parent_pages.as_ref().unwrap().inserted[0];assert_eq!(insertion.row,decode::<ParentPage>(&row["expected"]));assert_eq!(insertion.row.id.as_ptr(),id);assert_eq!(insertion.row.frames.as_ptr(),frames);assert_eq!(insertion.row.layers.as_ptr(),layers);assert_eq!(insertion.index,row["index"].as_u64().map(|i|i as usize).unwrap_or(base.borrow().get().parent_pages.len()));}close(&mut owner);retire(diff);retire(prepared);close_source(&mut authored);close_source(&mut base);}}}
